content:
{
  "findings": [
    {
      "title": "Exclusion criteria numbering is inconsistent and missing item 1",
      "page": 39,
      "quote": "1. Neutrophil count at or above 1200 /mm3.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 3b requires PD within 12 weeks of last dose, but criterion 3a requires treatment for 12 weeks or longer, creating potential contradiction",
      "page": 38,
      "quote": "a. Received treatment with a Food and Drug Administration approved PD-1 blocking antibody for 12 weeks or longer. b. Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 4c requires documented progression in previously radiated lesion, but exclusion criterion 2 allows radiation within 2 weeks before first dose, potentially conflicting",
      "page": 38,
      "quote": "c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 7a requires neutrophil count ≥1500/mm3, but exclusion criterion 1 (misplaced) says ≥1200/mm3, creating contradiction",
      "page": 39,
      "quote": "− neutrophil count ≥ 1500/mm3",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 11 references Section 4.3.2 for contraception, but that section is for acceptable methods, not for pregnancy testing; also pregnancy test timing is inconsistent with Section 4.3",
      "page": 39,
      "quote": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1 and be willing to use an adequate method of contraception (Section 4.3.2.)",
      "severity": "minor"
    },
    {
      "title": "Exclusion criteria list starts at 2, missing criterion 1",
      "page": 39,
      "quote": "2. Received radiation therapy (or other nonsystemic therapy) within 2 weeks before first dose of study treatment on W1D1.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 5 allows archival sample if no intervening therapy, but does not specify time limit for archival; also cross-reference to laboratory manual is missing section number",
      "page": 38,
      "quote": "A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received.",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 6 is a NOTE, not a criterion, and is out of place",
      "page": 38,
      "quote": "6. NOTE: for tissue sampling details, please refer to the laboratory manual.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 4 allows steroids ≤10 mg/day, but Section 4.4 prohibits systemic corticosteroids >10 mg/day at enrollment, which is consistent; however, exclusion criterion 4a says subjects on ≤10 mg/day do not need to discontinue, but Section 4.4 says not permitted at enrollment, creating ambiguity",
      "page": 39,
      "quote": "a. Subjects who are currently receiving steroids at a prednisone-equivalent dose of ≤ 10 mg/day do not need to discontinue steroids before enrollment.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 6 says not fully recovered from AEs to Grade 1 or less, but exception for persistent AEs; however, it does not specify time window for recovery, and cross-reference to CTCAE v5.0 is fine",
      "page": 40,
      "quote": "Not fully recovered from AEs (to Grade 1 or less [per CTCAE v5.0], with the exception of persistent adverse events or sequelae, eg, vitiligo, alopecia, hypothyroidism, diabetes mellitus, and adrenal and/or pituitary insufficiency) due to prior treatment.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 18 says within 30 days before start of Screening, but should be before first dose; also inconsistent with other time windows",
      "page": 41,
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening.",
      "severity": "minor"
    },
    {
      "title": "Section 4.5 says treatment discontinuation if >12 weeks, but also says 'does not restart within 12 weeks' and 'permanently discontinue (>12 weeks)' – inconsistent definition",
      "page": 43,
      "quote": "Treatment discontinuation is defined as any subject who stops receiving study treatment and does not restart within 12 weeks. Subjects who permanently discontinue (> 12 weeks) CMP-001 or nivolumab, may not be retreated with the discontinued study treatment in this study.",
      "severity": "minor"
    }
  ]
}
